// shell_bridge.test.ts — Exercises the actual WASM binary end-to-end.
//
// Loads shell.wasm in Node via wasm_exec.js, boots the shell with
// stub FS callbacks serving fixture data, feeds commands through
// wasmHandleInput, and asserts the write callback output matches the
// same expectations the Go-native test verifies.
//
// Fixtures are generated by `go generate ./shelltest/` — both the Go
// test and this test exercise the same cases, proving cross-environment
// parity between the CLI (native Go) and browser (Go→WASM→JS).

import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { describe, it, expect } from 'vitest'
import fixtures from './shell_fixtures.json'

// Load wasm_exec.js — it registers globalThis.Go
import './wasm_exec.js'

declare const Go: {
  new (): { importObject: WebAssembly.Imports; run(instance: WebAssembly.Instance): Promise<void> }
}

interface File {
  path: string
  content: string
  is_dir?: boolean
}

interface Case {
  name: string
  command: string
  // Pure-terminal contract: the client ships the line verbatim to the
  // executor. want_dispatch is the pipeline the WASM shell must dispatch
  // (via the startQuery callback) — it equals command, since nothing is
  // rendered or rewritten client-side.
  want_dispatch: string
}

interface Fixture {
  name: string
  files: File[]
  cases: Case[]
}

// Boot the WASM binary with given files as FS state. Returns a
// function to execute commands and read output.
async function bootShell(files: File[]): Promise<{
  exec: (command: string) => string
  dispatchedPipeline: () => string
  getDirStack: () => string[]
  setDirStack: (stack: string[]) => void
  queryResult: (text: string, err: string) => string
  completions: () => Array<[string, number]>
  setInput: (text: string) => void
  type: (data: string) => string
  followDone: (err: string) => string
}> {
  const wasmPath = resolve(__dirname, '../../public/shell.wasm')
  const wasmBuffer = readFileSync(wasmPath)

  const go = new Go()
  const { instance } = await WebAssembly.instantiate(wasmBuffer, go.importObject)
  void go.run(instance)

  let output = ''
  let dispatched = ''
  const completed: Array<[string, number]> = []

  const callbacks = {
    write: (data: string) => { output += data },
    // Pure-terminal: warp ships every command line here via ActionExec;
    // capture the pipeline so the test can assert ship-verbatim.
    startQuery: (pipeline: string) => { dispatched = pipeline },
    startFollow: () => {},
    cancelQuery: () => {},
    notifyQuit: () => {},

    fsReadFile: (path: string) => {
      const f = files.find(file => file.path === path && !file.is_dir)
      if (!f) return { error: `not found: ${path}` }
      return { content: f.content }
    },
    fsWriteFile: (_path: string, _content: string) => ({}),
    fsReadDir: (path: string) => {
      // Root listing: return all mount prefixes (mirrors MountFS behavior).
      if (path === '/' || path === '') {
        return { entries: ['bin/', 'cron.d/', 'etc/', 'log/', 'tmp/'] }
      }
      // /log listing: return apps.
      if (path === '/log') {
        return { entries: ['myapp.log'] }
      }
      const prefix = path.endsWith('/') ? path : path + '/'
      const seen = new Set<string>()
      const entries: string[] = []
      for (const f of files) {
        if (!f.path.startsWith(prefix)) continue
        const rest = f.path.slice(prefix.length)
        if (!rest) continue
        const slashIdx = rest.indexOf('/')
        const name = slashIdx >= 0 ? rest.slice(0, slashIdx) : rest
        const isDir = slashIdx >= 0 || !!f.is_dir
        const entry = isDir ? name + '/' : name
        if (!seen.has(entry)) {
          seen.add(entry)
          entries.push(entry)
        }
      }
      entries.sort()
      return { entries }
    },
    fsRemove: (path: string) => {
      if (path.startsWith('/log')) return { error: 'read-only filesystem' }
      return {}
    },

    loadHistory: () => '',
    saveHistory: () => {},
    getUser: () => 'test',
    getCustomer: () => 'testco',
    getServices: () => ['myapp'],
    fsGetWatchResults: () => ({ results: [] }),
    onRangeChange: () => {},
    builtinExecuted: () => {},
    // Host hook: every completed shell line, with its exit code.
    commandCompleted: (line: string, exitCode: number) => { completed.push([line, exitCode]) },
  }

  // wasmInit is registered by cmd/wasm/main.go
  const wasmInit = (globalThis as Record<string, unknown>).wasmInit as
    (width: number, height: number, cb: typeof callbacks) => void
  wasmInit(80, 24, callbacks)

  // Drain the initial render output.
  output = ''

  const wasmHandleInput = (globalThis as Record<string, unknown>).wasmHandleInput as
    (data: string) => void
  const g = globalThis as unknown as {
    wasmGetDirStack: () => string[]
    wasmSetDirStack: (stack: string[]) => void
    wasmHandleQueryResult: (text: string, err: string) => void
    wasmSetInput: (text: string) => void
    wasmHandleFollowDone: (err: string) => void
  }

  return {
    exec: (command: string) => {
      output = ''
      dispatched = ''
      // Feed each character then press Enter (\r).
      wasmHandleInput(command + '\r')
      return output
    },
    dispatchedPipeline: () => dispatched,
    setInput: (text: string) => g.wasmSetInput(text),
    type: (data: string) => {
      output = ''
      wasmHandleInput(data)
      return output
    },
    followDone: (err: string) => {
      output = ''
      g.wasmHandleFollowDone(err)
      return output
    },
    completions: () => completed.slice(),
    getDirStack: () => g.wasmGetDirStack() as string[],
    setDirStack: (stack: string[]) => g.wasmSetDirStack(stack),
    queryResult: (text: string, err: string) => {
      output = ''
      g.wasmHandleQueryResult(text, err)
      return output
    },
  }
}

// Pure-terminal parity: the WASM shell, like the native CLI, ships every
// command line verbatim to the executor (it renders no FS output itself).
// Each case asserts the pipeline the shell dispatched equals want_dispatch.
// Listing/read/permission semantics are the server's job, covered by the
// coordinator + integration suites.
for (const fixture of fixtures as Fixture[]) {
  describe(fixture.name, () => {
    for (const tc of fixture.cases) {
      it(tc.name, async () => {
        const shell = await bootShell(fixture.files)
        shell.exec(tc.command)
        expect(shell.dispatchedPipeline()).toBe(tc.want_dispatch)
      })
    }
  })
}

// Dirstack courier through the real wasm: the server owns cd, so the host
// reads the core's stack to ship with a request and writes back the stack
// the server returns. Writing it before delivering the result must make
// the redrawn prompt show the new cwd.
describe('dirstack courier (wasm exports)', () => {
  it('starts at the root and round-trips a stack set by the host', async () => {
    const shell = await bootShell([])
    expect(shell.getDirStack()[0]).toBe('/')
    shell.setDirStack(['/log/loom/prod/api', '/tmp'])
    expect(shell.getDirStack()).toEqual(['/log/loom/prod/api', '/tmp'])
  })

  it('ignores an empty stack instead of blanking the cwd', async () => {
    const shell = await bootShell([])
    shell.setDirStack(['/tmp'])
    shell.setDirStack([])
    expect(shell.getDirStack()).toEqual(['/tmp'])
  })

  it('redraws the prompt with the cwd a remote cd left behind', async () => {
    const shell = await bootShell([])
    shell.exec('cd /tmp')
    expect(shell.dispatchedPipeline()).toBe('cd /tmp')
    shell.setDirStack(['/tmp'])
    const redraw = shell.queryResult('', '')
    expect(redraw).toContain('/tmp')
  })
})

// Lesson/progress tracking is driven from the browser: the shell core
// publishes CommandCompleted for every line, and the wasm bridge forwards
// it to the host as commandCompleted(line, exitCode). That covers inline
// builtins (`history`) and lines whose pipe stages the client handles
// itself, which the server's exec-path never sees in full.
describe('commandCompleted host hook (wasm)', () => {
  const settle = () => new Promise(r => setTimeout(r, 30))

  it('reports an inline builtin with exit 0', async () => {
    const shell = await bootShell([])
    shell.exec('history')
    await settle()
    expect(shell.completions()).toContainEqual(['history', 0])
  })

  it('reports a dispatched line with the full text once its result arrives', async () => {
    const shell = await bootShell([])
    shell.exec('tail /log/a/b/main.log | grep ERROR')
    shell.queryResult('', '')
    await settle()
    expect(shell.completions()).toContainEqual(['tail /log/a/b/main.log | grep ERROR', 0])
  })

  it('reports a failed line with a non-zero exit code', async () => {
    const shell = await bootShell([])
    shell.exec('cat /log/nope.log')
    shell.queryResult('', 'boom')
    await settle()
    const done = shell.completions().find(([line]) => line === 'cat /log/nope.log')
    expect(done).toBeDefined()
    expect(done![1]).not.toBe(0)
  })
})

// The tour prefills the next command with setInput. Pressing Enter runs it;
// typing instead replaces it rather than appending (OB-6).
describe('prefilled input (wasm)', () => {
  it('runs an untouched prefill verbatim on Enter', async () => {
    const shell = await bootShell([])
    shell.setInput('cat /etc/notify.yaml')
    shell.type('\r')
    expect(shell.dispatchedPipeline()).toBe('cat /etc/notify.yaml')
  })

  it('is replaced, not appended to, by typing', async () => {
    const shell = await bootShell([])
    shell.setInput('cat /etc/notify.yaml')
    shell.exec('ls /tmp')
    expect(shell.dispatchedPipeline()).toBe('ls /tmp')
  })
})

// Ctrl+C stops a tail in the core; the host's cancellation then echoes back
// as a follow-done. That echo must not announce the stop a second time (OB-8).
describe('tail -f stop (wasm)', () => {
  it('prints [tail stopped] once across Ctrl+C and the cancellation echo', async () => {
    const shell = await bootShell([])
    shell.exec('tail -f /log/a/b/main.log')
    const out = shell.type('\x03') + shell.followDone('context canceled')
    expect(out.split('[tail stopped]').length - 1).toBe(1)
    expect(out).not.toContain('context canceled')
  })
})
